def run(_context):
    import adsk.cam
    import adsk.core

    cam = mb.get_cam()
    setup = cam.setups.itemByName("Setup1")

    for i in range(setup.operations.count):
        op = setup.operations.item(i)
        print(f"\n=== {op.name} ===")

        # Look for warning/error/time properties on operation
        for attr in sorted(dir(op)):
            al = attr.lower()
            if any(w in al for w in ['warn', 'error', 'time', 'cycle', 'duration', 'valid']):
                try:
                    val = getattr(op, attr)
                    if not callable(val):
                        print(f"  op.{attr}: {val}")
                except:
                    pass

        # Check toolpath properties
        tp = op.toolpath
        if tp:
            for attr in sorted(dir(tp)):
                al = attr.lower()
                if any(w in al for w in ['warn', 'error', 'time', 'cycle', 'duration', 'valid']):
                    try:
                        val = getattr(tp, attr)
                        if not callable(val):
                            print(f"  tp.{attr}: {val}")
                    except:
                        pass

