def run(_context):
    import json
    import re

    with open("C:/temp/Setup1.nc", "r") as f:
        lines = f.readlines()

    print("=== OPERATION HEADERS & TOOL CHANGES ===")
    for i, line in enumerate(lines):
        ls = line.strip()
        # Operation headers (comments)
        if re.match(r'^\([A-Z]', ls) and not ls.startswith('(Machine') and not ls.startswith('(  '):
            print(f"  Line {i+1}: {ls}")
        # Tool changes
        if 'M6' in ls or 'M01' in ls or ls == 'M0':
            print(f"  Line {i+1}: {ls}")
        # Spindle
        if re.match(r'^S\d+ M3', ls):
            print(f"  Line {i+1}: {ls}")
        # Coolant
        if re.match(r'^M[89]', ls):
            print(f"  Line {i+1}: {ls}")

    # Check pocket dimensions - look for X/Y values near pocket ops
    print("\n=== POCKET ROUGH SECTION (lines 235-400) ===")
    for i in range(234, min(400, len(lines))):
        ls = lines[i].strip()
        if ls and not ls.startswith('(') and not ls.startswith('%'):
            print(f"  {ls}")

    # Check the Z values for pocket rough - should not go below Z=-20.8
    print("\n=== ALL Z VALUES IN POCKET ROUGH ===")
    in_pocket_rough = False
    in_pocket_finish = False
    for i, line in enumerate(lines):
        ls = line.strip()
        if '(Pocket Rough)' in ls:
            in_pocket_rough = True
            in_pocket_finish = False
        elif '(Pocket Finish)' in ls:
            in_pocket_rough = False
            in_pocket_finish = True
        elif '(Outer Contour)' in ls:
            in_pocket_rough = False
            in_pocket_finish = False

        if in_pocket_rough or in_pocket_finish:
            z_matches = re.findall(r'Z-?[\d.]+', ls)
            for z in z_matches:
                zval = float(z.replace('Z',''))
                if zval < -20 and zval > -22:
                    print(f"  Line {i+1} [{'Rough' if in_pocket_rough else 'Finish'}]: Z={zval}")
